PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,public_no TEXT UNIQUE,created INTEGER,updated INTEGER,version INTEGER DEFAULT 1,access_version INTEGER DEFAULT 1,status TEXT,language TEXT,name TEXT,email TEXT,phone TEXT,business TEXT,requirements TEXT,items TEXT,estimate INTEGER,quote INTEGER,scope TEXT,method TEXT,idempotency TEXT UNIQUE,payload_hash TEXT);
CREATE TABLE IF NOT EXISTS stages(id TEXT PRIMARY KEY,order_id TEXT REFERENCES orders(id),phase TEXT,base INTEGER,fee INTEGER,total INTEGER,method TEXT,status TEXT,released INTEGER,paid INTEGER,reference TEXT,usdt TEXT,UNIQUE(order_id,phase));
CREATE TABLE IF NOT EXISTS receipts(id TEXT PRIMARY KEY,order_id TEXT REFERENCES orders(id),stage_id TEXT REFERENCES stages(id),created INTEGER,name TEXT,mime TEXT,path TEXT,sha TEXT,reference TEXT,status TEXT,note TEXT);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,order_id TEXT REFERENCES orders(id),stage_id TEXT REFERENCES stages(id),kind TEXT,number TEXT UNIQUE,created INTEGER,pdf BLOB,UNIQUE(stage_id,kind));
CREATE TABLE IF NOT EXISTS counters(name TEXT PRIMARY KEY,value INTEGER);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,created INTEGER,actor TEXT,order_id TEXT,action TEXT,detail TEXT);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,expires INTEGER);
CREATE TABLE IF NOT EXISTS limits(key TEXT,created INTEGER);
CREATE INDEX IF NOT EXISTS limits_key ON limits(key,created);
CREATE TABLE IF NOT EXISTS checkout(stage_id TEXT PRIMARY KEY,session_id TEXT UNIQUE,url TEXT,created INTEGER,expires INTEGER DEFAULT 0,generation INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS stripe_events(id TEXT PRIMARY KEY,created INTEGER,result TEXT);
CREATE TABLE IF NOT EXISTS outbox(id INTEGER PRIMARY KEY,created INTEGER,recipient TEXT,subject TEXT,body TEXT,status TEXT DEFAULT 'queued',attempts INTEGER DEFAULT 0,next_attempt INTEGER DEFAULT 0,error TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS settled_receipt_hash ON receipts(sha) WHERE status='approved';
CREATE TABLE IF NOT EXISTS project_plans(order_id TEXT PRIMARY KEY REFERENCES orders(id),delivery TEXT NOT NULL DEFAULT 'planning',priority TEXT NOT NULL DEFAULT 'normal',due_date TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS project_notes(id INTEGER PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),created INTEGER NOT NULL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_tasks(id INTEGER PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),title TEXT NOT NULL,due_date TEXT NOT NULL DEFAULT '',done INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS project_notes_order ON project_notes(order_id,id);
CREATE INDEX IF NOT EXISTS project_tasks_order ON project_tasks(order_id,done);
CREATE INDEX IF NOT EXISTS receipts_pending ON receipts(status,order_id);
CREATE TABLE IF NOT EXISTS sales_sessions(id TEXT PRIMARY KEY,created INTEGER NOT NULL,updated INTEGER NOT NULL,language TEXT NOT NULL,brief TEXT NOT NULL,recommendation TEXT NOT NULL DEFAULT 'none',qualified INTEGER NOT NULL DEFAULT 0,custom INTEGER NOT NULL DEFAULT 0,turns INTEGER NOT NULL DEFAULT 0,busy_until INTEGER NOT NULL DEFAULT 0,order_id TEXT REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS sales_messages(id INTEGER PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sales_sessions(id) ON DELETE CASCADE,role TEXT NOT NULL,content TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sales_turns(session_id TEXT NOT NULL REFERENCES sales_sessions(id) ON DELETE CASCADE,nonce TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(session_id,nonce));
CREATE INDEX IF NOT EXISTS sales_messages_session ON sales_messages(session_id,id);
CREATE TABLE IF NOT EXISTS owner_notifications(id INTEGER PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),created INTEGER NOT NULL,summary TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL DEFAULT 0,provider_id TEXT,error TEXT NOT NULL DEFAULT '');

CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT,verified INTEGER NOT NULL DEFAULT 0,google_sub TEXT UNIQUE,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS customer_sessions(token_hash TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS customer_orders(order_id TEXT PRIMARY KEY REFERENCES orders(id),customer_id TEXT NOT NULL REFERENCES customers(id),created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS customer_orders_owner ON customer_orders(customer_id);
CREATE TABLE IF NOT EXISTS account_challenges(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),kind TEXT NOT NULL,code_hash TEXT NOT NULL,expires INTEGER NOT NULL,created INTEGER NOT NULL,attempts INTEGER NOT NULL,used INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS google_flows(state_hash TEXT PRIMARY KEY,nonce TEXT NOT NULL,verifier TEXT NOT NULL,created INTEGER NOT NULL,session_binding TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customer_profiles(customer_id TEXT PRIMARY KEY REFERENCES customers(id),country_code TEXT NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS order_countries(order_id TEXT PRIMARY KEY REFERENCES orders(id),country_code TEXT NOT NULL,country_source TEXT NOT NULL,updated INTEGER NOT NULL);
